pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();

    // Dynamic horizon awareness
    let step_factor = (step_index as f64 / total_jobs as f64).powi(2);
    let active_nodes_factor = (active_nodes_count as f64 / total_jobs as f64).sqrt();

    // Lookahead awareness for the next job
    let can_fit_next_job = node_residual_cpu >= next_job_cpu && node_residual_ram >= next_job_ram;
    let lookahead_factor = if can_fit_next_job { 0.5 } else { 1.0 };

    // Non-linear conditionals and penalties
    let cpu_overload_penalty = if cpu_norm > 0.8 { (cpu_norm - 0.8).powi(2) } else { 0.0 };
    let ram_overload_penalty = if ram_norm > 0.8 { (ram_norm - 0.8).powi(2) } else { 0.0 };
    let imbalance_bonus = if imbalance_penalty < 0.1 { 0.5 - imbalance_penalty } else { 0.0 };

    // Combined score
